<script setup lang="ts">definePageMeta({middleware:'auth'});const {request}=useApi();const status=ref('');const {data,pending,error,refresh}=await useAsyncData('orders',()=>request<{data:any[]}>('/orders'+(status.value?'?status='+status.value:'')),{watch:[status]});</script><template><section><div class="flex justify-between mb-4"><h1 class="text-2xl font-bold">Orders</h1><NuxtLink to="/orders/create" class="bg-blue-700 text-white px-4 py-2 rounded">Create order</NuxtLink></div><select v-model="status" class="border p-2 rounded mb-4"><option value="">All status</option><option v-for="s in ['PENDING','PAID','SHIPPED','COMPLETED','CANCELLED']" :value="s">{{s}}</option></select><p v-if="pending">Loading…</p><p v-else-if="error">Failed to load orders.</p><table v-else class="w-full bg-white"><tr><th>Order</th><th>Customer</th><th>Status</th><th>Total</th></tr><tr v-for="o in data?.data" :key="o.id"><td><NuxtLink :to="`/orders/${o.id}`">{{o.order_number}}</NuxtLink></td><td>{{o.customer?.customer_name}}</td><td>{{o.status}}</td><td>Rp {{Number(o.total_amount).toLocaleString('id-ID')}}</td></tr></table></section></template>
